SELECT o.* FROM sys_order o join customer c on o.customer_id = c.id

    c.salesman_id = #{userId}

        and o.status = #{status}


        and o.create_time >= #{beginTime}


        and o.create_time <= #{endTime}


order by o.create_time desc

